
-- Traceability database stores only identifiers and relationships
-- needed to trace animals through parts, trays, and products.
--
-- Animal and farm details are stored in the animal-registration
-- database, managed by Spring Data JPA / Hibernate.
--
-- Part, tray, and product IDs are generated by their respective
-- station services, not by Traceability.

CREATE DATABASE traceability;

-- Animals registered by Station 1
CREATE TABLE animal
(
    registration_number VARCHAR(100) PRIMARY KEY
);

-- Parts originating from registered animals
CREATE TABLE part
(
    part_id INTEGER PRIMARY KEY,
    animal_registration_number VARCHAR(100) NOT NULL
        REFERENCES animal(registration_number)
);

-- Trays created by Station 2
CREATE TABLE tray
(
    tray_id INTEGER PRIMARY KEY
);

-- Parts assigned to trays
CREATE TABLE tray_part
(
    tray_id INTEGER NOT NULL REFERENCES tray(tray_id),
    part_id INTEGER NOT NULL REFERENCES part(part_id),

    PRIMARY KEY (tray_id, part_id),
    UNIQUE (part_id)
);

-- Products packaged by Station 3
CREATE TABLE product
(
    product_id INTEGER PRIMARY KEY
);

-- Trays used in products
CREATE TABLE product_tray
(
    product_id INTEGER NOT NULL REFERENCES product(product_id),
    tray_id INTEGER NOT NULL REFERENCES tray(tray_id),

    PRIMARY KEY (product_id, tray_id)
);

-- Tracks processed events to prevent duplicate processing
CREATE TABLE processed_event
(
    event_id UUID PRIMARY KEY,
    processed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
